parameters.jsCode:
// Extraer datos limpios del mensaje de WhatsApp
const item = $input.first().json;
let phone = '';
let name = 'Cliente';
let text = '';

if (item.source === 'whatsapp_cloud_api') {
  phone = item.client_phone;
  name = item.client_name;
  text = item.text;
} else if (item.entry && item.entry[0] && item.entry[0].changes) {
  const change = item.entry[0].changes[0].value;
  const message = change.messages && change.messages[0];
  const contact = change.contacts && change.contacts[0];

  phone = message ? message.from : '';
  name = contact ? contact.profile.name : 'Cliente';
  text = message && message.text ? message.text.body : '';
} else {
  phone = item.phone || '+573000000000';
  name = item.name || 'Cliente';
  text = item.text || item.message || '';
}

return [{
  json: {
    client_phone: phone,
    client_name: name,
    message_text: text,
    timestamp: new Date().toISOString()
  }
}];

